class Solution {
public:
    string repeatLimitedString(string s, int repeatLimit) {
        vector<int> count(26, 0);
        for (char ch : s) count[ch - 'a']++;
        priority_queue<pair<char, int>> pq;
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) pq.push({'a' + i, count[i]});
        }
        string res = "";
        while (!pq.empty()) {
            auto [ch, cnt] = pq.top();
            pq.pop();
            int use = min(cnt, repeatLimit);
            res.append(use, ch);
            cnt -= use;
            if (cnt > 0) {
                if (pq.empty()) break;
                auto [nCh, nCnt] = pq.top();
                pq.pop();
                res.push_back(nCh);
                nCnt--;
                if (nCnt > 0) pq.push({nCh, nCnt});
                pq.push({ch, cnt});
            }
        }
        return res;
    }
};

class Solution {
    public String repeatLimitedString(String s, int repeatLimit) {
        int[] count = new int[26];
        for (char ch : s.toCharArray()) count[ch - 'a']++;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) pq.offer(new int[]{i, count[i]});
        }
        StringBuilder sb = new StringBuilder();
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int ch = cur[0], cnt = cur[1];
            int use = Math.min(cnt, repeatLimit);
            for (int i = 0; i < use; i++) sb.append((char) ('a' + ch));
            cnt -= use;
            if (cnt > 0) {
                if (pq.isEmpty()) break;
                int[] next = pq.poll();
                sb.append((char) ('a' + next[0]));
                next[1]--;
                if (next[1] > 0) pq.offer(next);
                pq.offer(new int[]{ch, cnt});
            }
        }
        return sb.toString();
    }
}

var repeatLimitedString = function(s, repeatLimit) {
    const count = new Int32Array(26);
    for (let i = 0; i < s.length; i++) count[s.charCodeAt(i) - 97]++;
    let res = [];
    let i = 25;
    while (i >= 0) {
        if (count[i] === 0) {
            i--;
            continue;
        }
        const ch = String.fromCharCode(97 + i);
        const use = Math.min(count[i], repeatLimit);
        res.push(ch.repeat(use));
        count[i] -= use;
        if (count[i] > 0) {
            let j = i - 1;
            while (j >= 0 && count[j] === 0) j--;
            if (j < 0) break;
            res.push(String.fromCharCode(97 + j));
            count[j]--;
        }
    }
    return res.join('');
};
